const textBtn=(text,action)=>`<button class="text-btn" data-action="${action}">${text}${icon('right')}</button>`;
const ib=(ic,label,action)=>`<button class="icon-btn" aria-label="${label}" title="${label}" data-action="${action}">${icon(ic)}</button>`;
