function impact(){return `${heading('变更影响','让下一次变更有据可循，也让未知留在视野中。',btn('查看比较范围','compare','','impact'))}<div class="row" style="gap:12px;margin-bottom:24px"><select class="select" aria-label="比较起始来源版本"><option>r7 · 09-12 冻结</option></select>${icon('arrow')}<select class="select" aria-label="比较目标来源版本"><option>r8 · 当前版本</option></select><span class="micro">订单服务 · 4 个文件有变化</span></div><div class="impact-summary"><div><strong style="color:var(--blue)">3</strong><span>已确认路径</span></div><div><strong style="color:var(--amber)">2</strong><span>可能影响</span></div><div><strong>1</strong><span>尚不明确</span></div><p class="helper">这里提供分析建议。缺少覆盖依据时保持未知，不据此自动阻断合并或发布。</p></div><div class="section-head"><h2>建议优先核查</h2>${tag('建议性结果')}</div><div class="panel table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>受影响业务</th><th>判断</th><th class="optional-col">依据与限制</th><th>下一步</th></tr></thead><tbody>${[['取消订单','已确认','blue','状态校验方法发生变更','查看路径','focus-cancel'],['库存释放','可能影响','amber','关联调用变化，缺少执行记录','核查证据','go-evidence'],['支付超时关闭','未知','','动态回调的覆盖不足','查看缺口','gaps']].map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${tag(r[1],r[2])}</td><td class="optional-col muted" style="font-size:12px">${r[3]}</td><td>${textBtn(r[4],r[5])}</td></tr>`).join('')}</tbody></table></div></div><section class="panel pad" style="margin-top:24px"><div class="section-head"><h2>重验证建议</h2><span class="micro">尚未执行</span></div><div class="task-row" style="padding-top:0"><div class="circle-icon amber">${icon('test')}</div><div class="grow"><h3>未支付订单取消后，库存是否正确释放</h3><p>关联来源 r8、测试资产与环境后，再记录运行结果。</p></div>${tag('待验证','amber')}</div><p class="footnote">已确认的是有证据支撑的影响路径，并不是“变更正确”或“测试通过”。</p></section>`}
function settings(){const global=state.settingsScope==='global';return `${heading('设置中心','明确能力的作用范围，保留每次运行的配置依据。')}<div class="segment" style="margin-bottom:27px"><button aria-pressed="${global}" data-action="scope:global">${icon('globe')} 全局设置</button><button aria-pressed="${!global}" data-action="scope:workspace">${icon('folder')} 订单服务平台</button></div><div class="settings-layout"><nav class="settings-nav" aria-label="设置页导航"><div class="eyebrow" style="padding:9px 12px">${global?'全局资产':'工作区设置'}</div>${(global?[['accounts','user','账号'],['models','bot','模型'],['skills','grid','Skill'],['mcp','link','MCP']]:[['agents','bot','Agent 设置'],['capabilities','grid','能力管理']]).map(([id,ic,t])=>`<button class="nav-link ${state.settingsTab===id?'active':''}" style="border:0;background:${state.settingsTab===id?'var(--surface)':'transparent'}" data-action="settings-tab:${id}">${icon(ic)}${t}</button>`).join('')}</nav><div class="settings-sheet">${global?globalSettings():workspaceSettings()}</div></div>`}
function globalSettings(){const title={accounts:'账号与认证',models:'模型',skills:'Skill',mcp:'MCP'}[state.settingsTab]||'账号与认证';return `<div class="section-head"><h2>${title}</h2>${tag('全局范围')}</div><p class="helper" style="margin-bottom:23px">全局可用性是上限；工作区启用与 Agent 授权仍需分别配置。</p><section class="panel pad"><div class="settings-row"><div class="row"><div class="circle-icon purple">${icon('bot')}</div><div><h3>${title==='模型'?'已安装的模型 CLI':'代码分析账号'}</h3><p>最近验证：今天 09:12</p></div></div>${tag('可用','green')}</div><div class="settings-row"><div><h3>认证状态</h3><p>只展示安全摘要，敏感信息保持隐藏。</p></div><button class="btn" data-action="credential-info">查看认证说明</button></div></section>`}
function workspaceSettings(){const dirty=state.capability!==state.appliedCapability;return `<div class="section-head"><h2>${state.settingsTab==='capabilities'?'能力管理':'Agent 团队'}</h2>${tag('Ready · 已就绪','green')}</div><p class="helper">一个主 Agent 协调调查，子 Agent 在各自获授权的范围内工作。</p><div class="agent-list"><div class="agent-item"><div class="circle-icon purple">${icon('bot')}</div><div><h3>主 Agent · 业务调查</h3><small>规划、分派与回读核查</small></div></div><div class="agent-item"><div class="circle-icon blue">${icon('code')}</div><div><h3>子 Agent · 代码取证</h3><small>读取固定来源，返回证据</small></div></div></div><section class="panel pad"><div class="row between" style="margin-bottom:24px"><h3>主 Agent 配置</h3>${tag(dirty?'草稿有变更':'与已应用一致',dirty?'amber':'green')}</div><div class="settings-row"><div><h3>模型绑定</h3><p>使用已安装并验证的模型 CLI。</p></div><select class="select" aria-label="主 Agent 模型"><option>业务分析模型</option><option>代码分析模型</option></select></div><div class="settings-row"><div><h3>证据关联能力</h3><p>在工作区可用能力中显式授予当前 Agent。</p></div><input class="switch" type="checkbox" role="switch" id="capability-switch" aria-label="证据关联能力" ${state.capability?'checked':''}></div><div class="settings-row"><div><h3>代码阅读</h3><p>来源 r8 · 已授权范围</p></div>${tag('已授权','blue')}</div><div class="settings-row"><div><h3>执行配置快照</h3><p>运行保持启动时配置，恢复不会热切换授权。</p></div><span class="mono">profile-v6</span></div><div class="save-bar"><span class="helper">保存草稿与应用配置是两个动作。</span><div class="row">${btn('保存草稿','save-settings')}${btn('应用配置','apply-settings','primary')}</div></div></section>`}
function components(){return `${heading('组件展台','同一套基础语言，覆盖安静默认态与真实操作状态。',`<a class="btn" href="charter.html">阅读总纲 ${icon('external')}</a>`)}<div class="components-grid">
 <section class="panel specimen"><div class="eyebrow">01 / foundations</div><h2>瓷白、石墨与有节制的色彩</h2><div class="color-chips">${['var(--ink)','var(--secondary)','var(--line)','var(--bg)','var(--blue)','var(--purple)','var(--green)','var(--amber)'].map(c=>`<div class="swatch" style="background:${c}"></div>`).join('')}</div><div class="specimen-note">色彩表达选择、类型与状态。正文面保持不透明，玻璃效果只服务于导航和临时浮层。</div></section>
 <section class="panel specimen"><div class="eyebrow">02 / typography</div><h2>让信息自己建立层次</h2><div class="type-scale">${[['32','页面标题'],['20','区域标题'],['15','重要正文'],['13','列表正文'],['11','元信息']].map(([s,t])=>`<div><span style="font-size:${s}px;font-weight:${+s>18?600:400}">Aa 文</span><small>${s}px · ${t}</small></div>`).join('')}</div><div class="specimen-note">正文使用系统字体。长文提高到 15px / 1.8 行高；11px 只用于非关键元信息。</div></section>
 <section class="panel specimen"><div class="eyebrow">03 / actions</div><h2>按钮 · 明确而不喧闹</h2><div class="specimen-content"><div class="row">${btn('主要操作','sample-toast','primary')}${btn('次要操作','sample-toast')}${btn('轻量操作','sample-toast','ghost')}</div><div class="row"><button class="btn primary loading" disabled>处理中</button><button class="btn" disabled>不可用</button>${btn('删除草稿','delete-sample','danger')}${ib('plus','添加示例','sample-toast')}</div></div><div class="specimen-note">36px 默认高度，44px 触控目标。一个任务区只设一个主要操作；加载中保留宽度，重复提交被抑制。</div></section>
 <section class="panel specimen"><div class="eyebrow">04 / input</div><h2>文本输入 · 标签始终可见</h2><div class="form-grid">${field('sample-name','工作区名称','订单服务平台')}<div class="field"><label for="sample-error">仓库地址</label><input id="sample-error" class="input" aria-invalid="true" aria-describedby="sample-error-text" value="order-service"><span id="sample-error-text" class="field-error">请输入完整 HTTPS 仓库地址。</span></div></div><div class="specimen-note">占位文字不代替标签。错误发生在字段旁，说明修正方式；保留已输入内容。</div></section>
 <section class="panel specimen"><div class="eyebrow">05 / selection</div><h2>选择 · 用合适的控件</h2><div class="specimen-content"><div class="row"><select class="select" aria-label="组件示例来源版本"><option>r8 · 当前冻结版本</option><option>r7 · 历史版本</option></select><button class="btn" data-action="command">${icon('search')}搜索对象 <span class="micro">⌘ K</span></button></div><div class="row"><label class="checkbox"><input type="checkbox" checked>仅人工确认</label><label class="row" style="font-size:12px"><input class="switch" type="checkbox" role="switch" aria-label="示例自动恢复">自动恢复</label></div></div><div class="specimen-note">少量互斥项用分段控件；选项较多用下拉，跨对象检索用可搜索列表。支持键盘与 Esc 返回。</div></section>
 <section class="panel specimen"><div class="eyebrow">06 / status</div><h2>状态 · 不只靠颜色</h2><div class="specimen-content"><div class="row">${tag('人工确认','green')}${tag('Agent 分析','purple')}${tag('需要确认','amber')}</div><div class="row">${tag('已冻结','green')}${tag('等待调查')}${tag('访问受限','amber')}${tag('运行失败','red')}</div></div><div class="specimen-note">对象类型、证据权威、执行进度分别建模。“Agent 分析”不显示绿色勾；测试文件不显示“通过”。</div></section>
 <section class="panel specimen wide"><div class="eyebrow">07 / collection</div><h2>列表 · 对齐、密度与可追溯性</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>业务功能</th><th>状态</th><th>支撑依据</th><th>版本</th><th>操作</th></tr></thead><tbody><tr><td><strong>取消订单</strong><div class="sub">订单管理 / 生命周期</div></td><td>${tag('人工确认','green')}</td><td>3 条证据</td><td class="mono">r8 · g7</td><td>${textBtn('查看详情','focus-cancel')}</td></tr><tr><td><strong>库存释放</strong><div class="sub">库存管理 / 预占</div></td><td>${tag('Agent 分析','purple')}</td><td>2 条证据 · 1 项限制</td><td class="mono">r8 · g7</td><td>${textBtn('查看依据','go-evidence')}</td></tr></tbody></table></div><div class="specimen-note">52px 常规行高，72px 双行信息。没有选择时不显示批量操作条；筛选后的选择范围必须明确。</div></section>
 <section class="panel specimen wide"><div class="eyebrow">08 / resilience</div><h2>等待、空白与失败，也属于设计</h2><div class="state-grid"><div class="state-box"><h3>加载中 · 保持布局</h3><div class="skeleton" style="width:76%;margin:17px 0 12px"></div><div class="skeleton" style="width:52%"></div></div><div class="state-box"><h3>尚无来源快照</h3><p>添加一个 Git 仓库或目录，建立首份固定依据。</p>${textBtn('添加来源','new-source')}</div><div class="state-box"><h3>没有匹配的业务功能</h3><p>当前筛选不会删除数据，清空后可重新浏览。</p>${textBtn('清空筛选','clear-graph-filters')}</div><div class="state-box"><h3 style="color:var(--amber)">目录连接中断</h3><p>已采集 196 项，内容与清单保留。重新关联后继续。</p>${textBtn('重新连接','reconnect-source')}</div></div></section></div>`}
function render(){sidebar();toolbar();document.getElementById('main').innerHTML=({overview,sources,evidence,graph,impact,settings,components}[state.view]||overview)();attachGraphPan()}
function go(view){if(state.view===view){render();return}location.hash=view}
function selectNode(id){state.selected=id;state.inspectorTab='summary';render()}
const dialog=document.getElementById('dialog');let restoreFocus=null;
function openDialog(html,cls=''){restoreFocus=document.activeElement;dialog.className=cls;dialog.innerHTML=html;if(!dialog.open)dialog.showModal();queueMicrotask(()=>dialog.querySelector('[autofocus]')?.focus())}
function closeDialog(){dialog.close();restoreFocus?.focus()}
dialog.addEventListener('close',()=>restoreFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
function dialogShell(title,desc,body,actions=''){return `<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${ib('close','关闭对话框','close-dialog')}</div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`}
function newSource(){openDialog(dialogShell('添加来源','先保存来源草稿，采集与冻结保持独立步骤。',`<form id="source-form" novalidate class="stack" style="gap:20px">${field('source-name','来源名称','','例如：订单服务代码仓库')}<div class="field"><label for="source-url">Git 仓库地址</label><input autofocus id="source-url" name="source-url" class="input" placeholder="https://github.com/team/order-service" aria-describedby="source-url-hint"><span class="helper" id="source-url-hint">使用已获授权的仓库。本样稿只保存输入，不连接仓库。</span><span id="source-error" class="field-error" role="alert" hidden></span></div><div class="form-grid">${field('source-branch','分支 / 标签','main')}<div class="field"><label for="source-kind">来源类型</label><select id="source-kind" class="select"><option>Git 仓库</option></select></div></div></form>`,btn('取消','close-dialog')+'<button class="btn primary" type="submit" form="source-form">保存草稿</button>'))}
function review(){openDialog(dialogShell('确认退款规则的适用范围','订单管理 / 退款处理 · 问题 Q-03 · 来源 r8',`<div class="quote">需求 §3.2：“已支付订单通过退款流程处理。”<br>代码证据：取消接口仅允许待支付状态。</div><div class="field"><span class="field-label">本次只处理这一条命题</span><label class="choice"><input type="radio" name="review-choice" value="scoped" checked><span>限定为已支付订单<small>保留代码事实，明确这条退款规则的适用条件。</small></span></label><label class="choice"><input type="radio" name="review-choice" value="investigate"><span>证据仍不足，继续调查<small>将问题和补充说明返回调查，不产生人工确认结论。</small></span></label></div><div class="field"><label for="review-note">决定说明</label><textarea autofocus id="review-note" class="input" placeholder="写下适用条件或仍需调查的问题…">${esc(state.reviewNote)}</textarea><span class="helper">只影响当前命题，不批准整张子图；此样稿记录在本机浏览器中。</span></div>`,btn('暂缓','close-dialog')+btn('记录当前决定','submit-review','primary')))}
const commandItems=[['overview','工作区概览','home','继续工作与当前版本'],['sources','来源快照','layers','版本、材料与采集任务'],['evidence','技术证据','facts','对象、事实与缺口'],['graph','业务图谱','graph','业务、实现与覆盖'],['impact','变更影响','impact','差异与重验证建议'],['settings','设置中心','settings','全局与工作区能力'],['components','组件展台','grid','查看组件与状态规范'],['cancel','取消订单','graph','业务功能 · BIZ-024']];let commandIndex=0,commandMatches=commandItems;
function command(){commandIndex=0;openDialog(`<div class="palette-input">${icon('search')}<label class="skip" for="command-input">全局搜索</label><input autofocus id="command-input" role="combobox" aria-label="搜索页面或对象" aria-expanded="true" aria-controls="command-results" aria-autocomplete="list" placeholder="搜索页面、功能或材料…"><button class="icon-btn" data-action="close-dialog" aria-label="关闭搜索">${icon('close')}</button></div><h2 id="dialog-title" class="skip">全局搜索</h2><div id="command-results" class="palette-results" role="listbox"></div><div class="palette-footer"><span>↑ ↓ 选择</span><span>↵ 打开</span><span>Esc 关闭</span></div>`,'palette');renderCommands('')}
function renderCommands(q){commandMatches=commandItems.filter(r=>(r[1]+r[3]).includes(q));commandIndex=Math.min(commandIndex,Math.max(0,commandMatches.length-1));document.getElementById('command-results').innerHTML=commandMatches.length?commandMatches.map(([id,t,ic,d],i)=>`<div id="cmd-${i}" role="option" aria-selected="${i===commandIndex}" class="palette-result" data-action="command-go:${id}">${icon(ic)}<div class="grow">${t}<div class="micro" style="margin-top:4px">${d}</div></div>${i===commandIndex?'<span class="micro">↵</span>':''}</div>`).join(''):'<div class="empty" style="padding:28px"><p>没有匹配结果。试试业务名称或页面名称。</p></div>';const el=document.getElementById('command-input');if(commandMatches.length)el.setAttribute('aria-activedescendant','cmd-'+commandIndex);else el.removeAttribute('aria-activedescendant')}
function action(key){const [name,...rest]=key.split(':'),value=rest.join(':');switch(name){
 case'go-sources':go('sources');break;case'go-evidence':go('evidence');break;case'go-impact':go('impact');break;
 case'focus-cancel':state.selected='cancel';state.graphMode='business';state.graphList=matchMedia('(max-width:767px)').matches;go('graph');break;
 case'workspace-settings':state.settingsScope='workspace';state.settingsTab='agents';go('settings');break;
 case'menu':document.getElementById('sidebar').classList.toggle('open');document.getElementById('scrim').hidden=!document.getElementById('sidebar').classList.contains('open');break;
 case'new-source':newSource();break;case'review':review();break;case'close-dialog':closeDialog();break;case'command':command();break;
 case'command-go':closeDialog();value==='cancel'?action('focus-cancel'):go(value);break;
 case'graph-mode':state.graphMode=value;render();break;case'graph-presentation':state.graphList=value==='list';render();break;case'node':selectNode(value);break;
 case'close-inspector':state.selected=null;render();break;case'inspect-tab':state.inspectorTab=value;render();break;
 case'zoom-in':state.zoom=Math.min(1.8,state.zoom+.15);render();break;case'zoom-out':state.zoom=Math.max(.65,state.zoom-.15);render();break;case'zoom-fit':state.zoom=1;state.pan={x:0,y:0};render();break;
 case'expand-graph':state.graphExpanded=true;render();toast('已展开相关库存释放节点；新关系仍保留待核实状态。');break;
 case'graph-help':openDialog(dialogShell('沿着证据探索','图谱保留关系方向与状态。',`<p class="inspector-copy">点击节点查看详情，点击连线查看关系依据。拖动画布平移，用 + / − 缩放。Tab 可依次选择节点与关系，Enter 打开。需要逐行阅读时，切换到列表视图。</p><p class="helper">按 Esc 关闭详情或对话框。仅人工确认筛选不会删除其他分析结果。</p>`));break;
 case'source-tab':state.sourceTab=value;render();break;case'clear-search':state.search='';render();break;
 case'source-detail':if(value&&decodeURIComponent(value)!=='订单服务 · r8'){openDialog(dialogShell(decodeURIComponent(value),'来源版本记录',`<p class="inspector-copy">${decodeURIComponent(value).includes('草稿')?'该来源仅保存为演示草稿，尚无冻结身份或材料数量。':'历史来源保留独立身份。本样稿只展开 r8 的材料内容，不借用当前版本填充历史记录。'}</p>`));break;}openDialog(dialogShell('来源 r8','当前冻结版本 · 214 项材料',`<dl class="metadata"><dt>来源</dt><dd>Git + 业务需求目录</dd><dt>固定提交</dt><dd class="mono">a8e2c41</dd><dt>冻结时间</dt><dd>2026-09-15 09:42</dd><dt>保存状态</dt><dd>已冻结，可回查</dd></dl><p class="helper">冻结身份与当前使用准入分别判断。示例不连接真实来源。</p>`,btn('浏览材料','show-inventory','primary')));break;
 case'show-inventory':closeDialog();state.sourceTab='inventory';go('sources');break;
 case'reconnect-source':openDialog(dialogShell('重新连接业务需求目录','之前的材料清单和已校验内容均保留。',`<div class="notice">${icon('folder')}<span>本样稿演示恢复后的界面状态，不会访问本地目录。</span></div><p class="inspector-copy">真实采集器将重新核对目录身份与材料清单；存在差异时先展示变化，再决定后续动作。</p>`,btn('取消','close-dialog')+btn('查看恢复后的状态','simulate-reconnect','primary')));break;
 case'simulate-reconnect':state.sourceRecovery=true;closeDialog();go('sources');toast('演示目录已重新关联，原有进度保留。');break;
 case'resume-source':toast('演示已进入等待采集状态；未启动真实采集任务。');break;
 case'evidence-tab':state.evidenceTab=value;render();break;case'gaps':state.evidenceTab='coverage';go('evidence');break;
 case'object':if(value==='OrderService'){toast('当前已展开 OrderService.cancel')}else if(value.includes('.'))action('evidence-preview:'+value);else openDialog(dialogShell(value,'来源 r8 · 对象定位示例',`<p class="inspector-copy">${value==='PaymentService'?'已定位此静态服务对象。完整提取记录将在技术证据实现阶段接入。':'此目录用于分组和定位材料；当前样稿展开了 OrderService 的完整示例。'}</p>`));break;
 case'evidence-preview':openDialog(dialogShell(value,'固定来源 r8 · 原文与解释分别保留',`<div class="quote">${value.includes('.java')?'L86：requireOwner(order, actor);<br>L87：requireState(order, PENDING_PAYMENT);':value.includes('.spec')?'测试定义：“未支付订单取消后释放库存”。<br>当前未关联该来源版本的真实执行记录。':'§3.2：未支付订单允许由下单用户取消。已支付订单通过退款流程处理。'}</div><p class="helper">以上内容是为验证 UX 构造的示例材料。</p>`,btn('关闭','close-dialog')));break;
 case'submit-review':{const choice=document.querySelector('input[name="review-choice"]:checked').value,note=document.getElementById('review-note').value;state.reviewNote=note;if(choice==='scoped')state.decisions.push({id:'DEMO-D-'+Date.now(),note,claim:'退款规则限于已支付订单',at:new Date().toISOString()});persist();closeDialog();render();toast(choice==='scoped'?'当前命题的演示决定已记录，其他节点保持原状态。':'补充说明已保存，问题继续保留为待调查。');break;}
 case'decision-history':openDialog(dialogShell('人工决定记录','每次决定只作用于选定命题。',state.decisions.map(d=>`<div class="quote"><strong>${esc(d.claim)}</strong><p>${esc(d.note||'未填写附加说明')}</p><span class="micro">${esc(d.id)} · 本机演示</span></div>`).join('')||'<p class="helper">尚无人工决定。</p>'));break;
 case'scope':state.settingsScope=value;state.settingsTab=value==='global'?'accounts':'agents';render();break;case'settings-tab':state.settingsTab=value;render();break;
 case'save-settings':persist();toast('演示草稿已保存在本机，尚未应用。');break;case'apply-settings':openDialog(dialogShell('应用当前配置','仅作用于订单服务平台的新运行。',`<p class="inspector-copy">证据关联能力：${state.capability?'启用':'停用'}。已有运行保留启动时配置；这个样稿仅更新演示状态。</p>`,btn('取消','close-dialog')+btn('应用配置','confirm-settings','primary')));break;
 case'confirm-settings':state.appliedCapability=state.capability;persist();closeDialog();render();toast('演示配置已应用，已有运行快照保持不变。');break;
 case'clear-graph-filters':state.onlyHuman=false;state.graphMode='business';state.graphList=matchMedia('(max-width:767px)').matches;go('graph');break;
 case'delete-sample':openDialog(dialogShell('删除这个演示草稿？','危险操作说明对象与后果。',`<p class="inspector-copy">这是一张确认对话框的组件示例，不删除真实数据。</p>`,btn('取消','close-dialog')+btn('删除演示草稿','delete-confirm','danger')));break;case'delete-confirm':closeDialog();toast('演示草稿已删除（无真实数据变更）。');break;
 case'sample-toast':toast('操作反馈示例：已完成。');break;
 case'workspace':openDialog(dialogShell('切换工作空间','工作空间选择与设置范围保持明确。',`<button class="workspace-switch" style="margin:0" data-action="close-dialog"><span class="workspace-avatar">订</span><div class="grow"><strong>订单服务平台</strong><div class="micro">当前工作空间</div></div>${icon('check')}</button><p class="helper">此样稿只提供一个示例工作空间，避免伪造跨空间数据。</p>`));break;
 case'compare':openDialog(dialogShell('比较范围','r7 → r8 · 建议性分析',`<p class="inspector-copy">固定比较同一工作区的两个来源快照。3 条路径有依据，2 条可能受影响，1 条保持未知。</p><p class="helper">正式比较需重新绑定事实集、业务关系和执行依据，不能把 r7 的确认静默扩展到 r8。</p>`));break;
 case'activity':openDialog(dialogShell('最近活动','状态跟随具体任务，历史集中回查。',`<div class="stack"><p class="inspector-copy">09:42　业务图谱 g7 已更新</p><p class="inspector-copy">09:40　技术证据 f12 已封存</p><p class="inspector-copy">09:32　来源快照 r8 已冻结</p></div>`));break;
 case'help':openDialog(dialogShell('随手可用的快捷键','操作入口始终也能通过鼠标与触控访问。',`<dl class="metadata"><dt>搜索页面与对象</dt><dd>⌘ / Ctrl + K</dd><dt>选择搜索结果</dt><dd>↑ / ↓</dd><dt>打开所选项</dt><dd>Enter</dd><dt>关闭当前浮层</dt><dd>Esc</dd><dt>浏览图谱节点</dt><dd>Tab → Enter</dd></dl>`));break;
 case'account':openDialog(dialogShell('Sky','工作区管理员',`<p class="inspector-copy">当前为 Traqen 设计提案样稿。账号、数据与权限均为演示。</p>`));break;
 case'credential-info':openDialog(dialogShell('认证信息展示规范','全局设置 / 账号',`<p class="inspector-copy">展示账号名称、认证状态与重新认证入口。令牌正文不出现在列表、错误提示或示例日志中。</p>`));break;
 default:toast('该入口属于设计说明。');}}
document.addEventListener('click',e=>{const edge=e.target.closest('[data-edge]');if(edge){const[a,b]=edge.dataset.edge.split(':'),from=graphNodes.find(n=>n.id===a),to=graphNodes.find(n=>n.id===b),rel=graphEdges.find(r=>r[0]===a&&r[1]===b)?.[2]||'影响待核实';openDialog(dialogShell(`${from?.title||a} → ${to?.title||b}`,'关系有方向，依据与状态跟随这一条关系。',`<dl class="metadata"><dt>关系类型</dt><dd>${rel}</dd><dt>来源 / 图谱</dt><dd>r8 / g7</dd><dt>成立范围</dt><dd>当前命题与对应版本</dd></dl><div class="quote">${rel.includes('待')?'当前证据尚不足，保留为待查关系。':a==='order'?'业务目录 §2 的功能归属陈述是此包含关系的示例依据。':b==='test'?'测试定义引用取消订单行为；当前没有关联执行记录。':b==='api'?'API-024 绑定 OrderService.cancel；业务解释引用需求 §3.2。':'需求 §3.2 是取消订单规则的原文引用。'}</div>`));return}const node=e.target.closest('[data-node]');if(node){selectNode(node.dataset.node);return}const target=e.target.closest('[data-action]');if(target)action(target.dataset.action)});
document.addEventListener('submit',e=>{if(e.target.id!=='source-form')return;e.preventDefault();const input=document.getElementById('source-url'),error=document.getElementById('source-error'),url=input.value.trim(),name=document.getElementById('source-name').value.trim();let valid=false;try{const u=new URL(url);valid=u.protocol==='https:'&&Boolean(u.hostname)&&u.pathname!=='/'}catch{}if(!valid){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','source-error');error.hidden=false;error.textContent='请输入完整 HTTPS 仓库地址，例如 https://github.com/team/order-service。';input.focus();return}if(!name){const el=document.getElementById('source-name');el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','source-error');error.hidden=false;error.textContent='请填写来源名称，方便在版本列表中辨认。';el.focus();return}state.sources.unshift({name,url});state.search='';persist();closeDialog();go('sources');toast('来源草稿已保存到本机样稿，未连接真实仓库。')});
document.addEventListener('input',e=>{if(e.target.id==='source-search'){state.search=e.target.value;document.getElementById('source-rows').innerHTML=sourceRows()}if(e.target.id==='command-input'){commandIndex=0;renderCommands(e.target.value)}if(e.target.id==='review-note'){state.reviewNote=e.target.value;persist()}});
document.addEventListener('change',e=>{if(e.target.id==='only-human'){state.onlyHuman=e.target.checked;render()}if(e.target.id==='capability-switch'){state.capability=e.target.checked;persist();render()}if(e.target.id==='graph-version'){e.target.selectedIndex=0;toast('当前样稿只提供 g7；历史版本选择的产品规则见设计总纲。')}});
document.addEventListener('keydown',e=>{if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...e.target.closest('[role=tablist]').querySelectorAll('[role=tab]')];let i=tabs.indexOf(e.target);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].focus();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();command();return}if(e.target.id==='command-input'){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+commandMatches.length)%Math.max(1,commandMatches.length);renderCommands(e.target.value)}if(e.key==='Enter'&&!e.isComposing&&commandMatches[commandIndex]){e.preventDefault();action('command-go:'+commandMatches[commandIndex][0])}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-node],[data-edge]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(e.key==='Escape'&&!dialog.open){if(document.getElementById('sidebar').classList.contains('open')){document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').hidden=true}else if(state.selected){state.selected=null;render()}}});
document.getElementById('scrim').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('scrim').hidden=true});
document.getElementById('theme-toggle').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';applyTheme();persist()});
function attachGraphPan(){const svg=document.getElementById('graph-svg');if(!svg)return;let drag=null;svg.addEventListener('pointerdown',e=>{if(e.target.closest('[data-node],[data-edge]'))return;drag={x:e.clientX,y:e.clientY,px:state.pan.x,py:state.pan.y};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;const scale=785/svg.getBoundingClientRect().width;state.pan={x:drag.px+(e.clientX-drag.x)*scale,y:drag.py+(e.clientY-drag.y)*scale};document.getElementById('graph-transform').setAttribute('transform',`translate(${state.pan.x} ${state.pan.y}) translate(392 295) scale(${state.zoom}) translate(-392 -295)`) });svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null)}
function route(){const view=location.hash.slice(1).split('?')[0];state.view=['overview','sources','evidence','graph','impact','settings','components'].includes(view)?view:'overview';document.getElementById('scrim').hidden=true;render();window.scrollTo(0,0)}
window.addEventListener('hashchange',route);applyTheme();route();
window.__traqenDemo={state,render,go,icon};
